-- Fictional clubs, club accounts, entitlements, players, saved players, sessions, rosters, waitlists, join requests and match
-- requests for the Queue write characterization (apps/queue/src/app/api POST routes). Applied on top of the Prisma migrations.
-- Accounts are linked with auth_provider 'supabase' (the TypeScript side); the Go test relinks them to its own sign-in
-- identities. Every time is a fixed instant: no now() reaches a row, so a snapshot never depends on when it ran. Foreign key
-- checks are off for this load. Edit by hand and rerun apps/api/testdata/tools/capture-writes-queue.test.mjs.
BEGIN;
SET LOCAL session_replication_role = replica;

-- ---- start clean: the file is also the reset between cases, so it removes what it inserts ----
DELETE FROM player_notifications; DELETE FROM admin_audit_events; DELETE FROM player_rank_current; DELETE FROM sync_operations; DELETE FROM device_session_streams;
DELETE FROM session_publication_events; DELETE FROM session_publications; DELETE FROM result_exports; DELETE FROM session_result_snapshots; DELETE FROM projection_jobs;
DELETE FROM player_history_attributions; DELETE FROM club_session_player_summaries; DELETE FROM session_finalizations; DELETE FROM sync_conflicts; DELETE FROM club_session_reservations; DELETE FROM match_decisions;
DELETE FROM player_match_facts; DELETE FROM active_court_holds; DELETE FROM active_player_holds; DELETE FROM match_court_usage; DELETE FROM match_participations; DELETE FROM match_decisions; DELETE FROM matches;
DELETE FROM session_match_request_spots; DELETE FROM session_match_requests; DELETE FROM session_drop_out_notices; DELETE FROM session_invite_codes;
DELETE FROM session_payment_marks; DELETE FROM session_shuttle_plan_lines; DELETE FROM session_cost_estimates; DELETE FROM inventory_items;
DELETE FROM session_join_requests; DELETE FROM session_waitlist; DELETE FROM club_assessments; DELETE FROM session_players;
DELETE FROM session_hosts; DELETE FROM club_trusted_hosts;
DELETE FROM session_courts; DELETE FROM queue_sessions; DELETE FROM club_venues;
DELETE FROM club_player_private_inputs; DELETE FROM club_player_claim_links; DELETE FROM player_claim_links; DELETE FROM club_players; DELETE FROM shared_player_entries;
DELETE FROM player_accounts; DELETE FROM player_private_contacts; DELETE FROM player_id_allocations; DELETE FROM player_id_counters; DELETE FROM players;
DELETE FROM club_entitlements; DELETE FROM club_license_terms; DELETE FROM club_accounts; DELETE FROM clubs; DELETE FROM admin_accounts;

-- ---- clubs: Smash Club (the one that writes), Lapsed Club (its entitlement ended), Other Club (another club's rows) ----

-- ---- saved venues (Smash Club has two, Other Club one) ----

-- ---- registered players (with an account, so they have an inbox) and one unclaimed profile ----

-- Open shared entries of unclaimed people: Una (a Smash record), Eve (no Smash record yet) and Uri (Lapsed Club's record).

-- ---- saved players ----

-- ---- sessions: S1 prepared with an open slot, S2 prepared and full, S3 live, S4 completed, S5 across midnight, S6 across noon;
-- Lapsed Club's S7 (prepared) and S8 (live, started under a licence term); Other Club's S9 ----

-- ---- rosters (a level of 3 is intermediate_low): S1 Hal; S2 Hal and Ivy (full); S3 Hal and Jo here, Ivy away; S4 Hal ----
-- Requests: S1 has a guest, a registered player (Ann), a waitlist-placement guest, a declined and a confirmed one; S2 has Ann's
-- request to join from the waitlist and a guest; S3 has a guest to join from the waitlist; Other Club has one.
-- Match requests of the live night: Hal asks for a partner who is away (closes when the roster changes), Ivy, who is away, asks
-- for anyone (closes), Jo asks for Hal (stays), and a closed one.
COMMIT;
